private static let expiringSoonThresholdDays = 7

enum CalculationError: Error, Equatable, Sendable {
    case dayCalculationFailed
}

/// 今日から7日後までを「期限が近い」とする。期限日の時刻は判定に含めない。
static func calculate(
    expirationDate: Date?, now: Date, calendar: Calendar
) -> Result<ExpirationState, CalculationError> {
    guard let expirationDate else {
        return .success(.unset)
    }

    let today = calendar.startOfDay(for: now)
    let expirationDay = calendar.startOfDay(for: expirationDate)

    guard expirationDay >= today else {
        return .success(.expired)
    }

    guard let lastSoonDay = calendar.date(byAdding: .day, value: Self.expiringSoonThresholdDays, to: today) else {
        return .failure(.dayCalculationFailed)
    }

    if expirationDay <= lastSoonDay {
        return .success(.expiringSoon)
    }

    return .success(.normal)
}

init(expirationDate: Date?, now: Date, calendar: Calendar) {
    let dateStyle = Date.FormatStyle(
        date: .abbreviated, time: .omitted, calendar: calendar, timeZone: calendar.timeZone
    )
    let dateText = expirationDate?.formatted(dateStyle) ?? "期限未設定"
    let warning: (text: String, color: Color)?
    switch ExpirationState.calculate(expirationDate: expirationDate, now: now, calendar: calendar) {

        let text = warning.map { "\(dateText)（\($0.text)）" } ?? dateText
        detailText = text
        rowText = expirationDate == nil ? text : "賞味期限: \(text)"
        warningColor = warning?.color
    }
}

struct InventoryExpirationLabel: View {
    let text: String
    let warningColor: Color?

    var body: some View {
        HStack(alignment: .firstTextBaseline, spacing: 4) {
            if let warningColor {
                Image(systemName: "exclamationmark.circle.fill")
                    .foregroundStyle(warningColor)
                    .accessibilityHidden(true)
            }

            Text(text)
                .fontWeight(warningColor == nil ? nil : .semibold)
                .foregroundStyle(warningColor == nil ? Color.secondary : Color.primary)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

@MainActor
private func assertItemExpiration(isEnabled: Bool, in app: XCUIApplication) {
    let dateField = app.datePickers["item-form-expiration"]
    if isEnabled {
        XCTAssertTrue(dateField.waitForExistence(timeout: 5), app.debugDescription)
    } else {
        let unsetLabel = app.staticTexts["期限未設定"]
        XCTAssertTrue(unsetLabel.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(dateField.waitForNonExistence(timeout: 5), app.debugDescription)
    }

    let toggle = app.switches["item-form-has-expiration"]
    let expectedValue = isEnabled ? "1" : "0"
    XCTAssertEqual(toggle.value as? String, expectedValue, app.debugDescription)
}
